import{_ as r,l as o,o as e,c as n,v as t,p as h,x as i,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"PEB 反应扩散模型","description":"","frontmatter":{"title":"PEB 反应扩散模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/peb-reaction-diffusion.md","filePath":"litho/peb-reaction-diffusion.md","lastUpdated":1789023840000}'),d={name:"litho/peb-reaction-diffusion.md"};function c(f,a,B,_,m,P){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="peb-反应扩散模型" tabindex="-1">PEB 反应扩散模型 <a class="header-anchor" href="#peb-反应扩散模型" aria-label="Permalink to &quot;PEB 反应扩散模型&quot;">​</a></h1><div class="epigraph"><p>后烘不是把酸图乘一个增益常数：酸边走边催化，脱保护场是反应–扩散方程的解，不是曝光结束时那张快照。</p><footer>—— 据 Mack 对 PEB 反应–扩散与催化脱保护的论述整理</footer></div><p><a href="/litho/exposure-kinetics-acid">上一课</a>把曝光停在生成酸 \\(h(x,z)\\)。<a href="/litho/peb-bake">PEB 温度</a>已经说明热板是增益与扩散的公共执行器；<a href="/litho/acid-diffusion-lwr">酸扩散与 LWR</a>已经把扩散长度 \\(\\ell\\) 写成模糊核。缺口是把这两面收成一组方程，而不是再报一次烘箱设定。本课钉 PEB 反应–扩散。淬灭剂如何作为汇出现在方程里，留给<a href="/litho/quencher-neutralization">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>曝光结束时保护基大多还在。PEB 期间酸浓度 \\(h\\) 满足扩散，同时以某种速率消耗保护基分数 \\(m\\)（此处 \\(m\\) 是仍被保护的比例，不要与 Dill 的 PAC 分数混名）。紧凑形式常写成</p> \\[\\frac{\\partial h}{\\partial t}=\\nabla\\cdot(D\\nabla h)-k_q h q+\\cdots,\\qquad \\frac{\\partial m}{\\partial t}=-k_a h\\,m \\]<p>一类：第一式是酸的输运与反应损失，第二式是催化脱保护。\\(D\\) 随温度 Arrhenius 上升，于是「升温更敏」和「升温更糊」是同一组解的两个读出。</p><p>缺口不是再讲 CAR 循环，而是：平均场模拟器（PROLITH 族）解的是这组 PDE，OPC 紧凑核只保留其稳态后果——一颗宽度 \\(\\sim\\sqrt{Dt}\\) 的模糊。把紧凑核当成「没有反应–扩散」，会在标定换 PEB 时找不到该动哪一项。</p><h3 id="增益与模糊必须同一次积分" tabindex="-1">增益与模糊必须同一次积分 <a class="header-anchor" href="#增益与模糊必须同一次积分" aria-label="Permalink to &quot;增益与模糊必须同一次积分&quot;">​</a></h3><p>只积分脱保护、把 \\(h\\) 钉在出生点，会高估衬度、低估 \\(\\ell\\)。只卷积高斯、不让 \\(m\\) 被催化消耗，会让酸永远存在、暗区被走穿。实验室 FEM 对 PEB 时间的敏感，来自这次联立，不是来自剂量环。</p><p><span class="marginnote">\\(D\\) 可以依赖自由体积与残留溶剂，后课 <a href="/litho/tg-free-volume">Tg</a> 与 <a href="/litho/pab-solvent">PAB</a> 会改系数。本课先把方程形态钉住，不把某胶 5 nm 扩散写成常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程模型：指定 \\(D(T)\\)、催化速率 \\(k_a(T)\\)、时间 \\(t_\\mathrm{PEB}\\)，以上一课的 \\(h\\) 为初值。输出是脱保护场 \\(1-m\\)，送给显影速率。表征：固定光学，扫 \\(T\\) 与 \\(t\\)，看 CD 与 LWR——与热板课同一组实验，本课要求拟合时同时报 \\(D\\) 与 \\(k_a\\)，禁止只用「热剂量」一个数。</p><p><a href="/litho/acid-diffusion-lwr">酸扩散与 LWR</a> 的高斯核是 \\(k_a\\to\\infty\\)、无淬灭、常系数 \\(D\\) 时的近似。有限催化与消耗会让有效核更短、形状非高斯。紧凑 OPC 仍可用高斯，但换 PEB 必须重校准，不能只改光学 TCC。</p>',14)),(e(),h(E,null,{default:i(()=>[p(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20H0%5B%22%E6%9B%9D%E5%85%89%E9%85%B8%E5%9B%BE%20h%22%5D%20--%3E%20RD%5B%22%E5%8F%8D%E5%BA%94-%E6%89%A9%E6%95%A3%20PDE%22%5D%0A%20%20T%5B%22PEB%20%E6%B8%A9%E5%BA%A6%20%2F%20%E6%97%B6%E9%97%B4%22%5D%20--%3E%20RD%0A%20%20RD%20--%3E%20M%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E5%9C%BA%201-m%22%5D%0A%20%20RD%20--%3E%20ELL%5B%22%E6%9C%89%E6%95%88%20%E2%84%93%22%5D%0A%20%20M%20--%3E%20DEV%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%98%BE%E5%BD%B1%20R%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>酸做随机行走，每一步有一定概率让附近保护基脱落。亮区 \\(h\\) 高，\\(m\\) 掉得快；边沿 \\(h\\) 低，脱保护抢在酸被耗尽或走掉之前。扩散把亮区酸送进暗区，把暗区尚未中和的碱（下一课）送进来，等值面外推。Mack 强调：PEB 既是化学时钟也是空间低通，本课把这句话写成可积分的场。</p><p>片内温度不均匀等于本地 \\(D\\) 与 \\(k_a\\) 不同，CD 指纹跟热板走——热板课已经要求与剂量指纹对拍。反应–扩散模型是那次对拍在方程里的位置。</p><p><span class="marginnote">负胶 CAR 把「脱保护」换成交联动力学，扩散项仍在。不要把正胶的 \\(k_a\\) 抄到交联胶上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在这里展开淬灭剂的双分子速率——下一课补 \\(k_q h q\\)。不写 LWR 功率谱，谱是随机单元的题目；平均场 \\(\\ell\\) 只提供那张谱的化学低通。也不把 SAMPLE / PROLITH 的某一版离散格式写成物理定律。</p><p>EUV 金属氧化物的后烘往往不是酸催化 PDE，本课默认正性 CAR。换胶族等于作废 \\(D\\) 与 \\(k_a\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEB 用反应–扩散把酸图变成脱保护场；增益与 \\(\\ell\\) 同一次积分。</li><li>紧凑高斯核是这组 PDE 的工程近似，换 PEB 必须重校准。</li><li>\\(D(T)\\) 与 \\(k_a(T)\\) 禁止折成单一「热剂量」。</li><li>淬灭作为汇，下一课写入方程。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>（PEB 反应–扩散）。</li></ul>',9))])}const A=r(d,[["render",c]]);export{D as __pageData,A as default};
